from playwright.sync_api import sync_playwright
from pathlib import Path
import shutil
html=(Path(__file__).resolve().parents[1]/'public/workspace/index.html').read_text()
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox']); page=b.new_page(viewport={'width':1440,'height':950},accept_downloads=True); errs=[];page.on('pageerror',lambda e:errs.append(str(e)));page.set_content(html)
 def nav(n): page.locator(f'.nav[data-value="{n}"]').click()
 def actor(n): page.locator('#actor').select_option(n)
 def click(n): page.locator(f'[data-action="{n}"]').first.click()
 def fill(n,v): page.locator(f'#modal [name="{n}"]').first.fill(v)
 def sel(n,v): page.locator(f'#modal [name="{n}"]').first.select_option(v)
 def submit(): page.locator('#modal button[type=submit]').first.click()
 def row(text): return page.locator('tr').filter(has_text=text)
 def draw():
  c=page.locator('#sig'); c.scroll_into_view_if_needed(); q=c.bounding_box();page.mouse.move(q['x']+20,q['y']+20);page.mouse.down();page.mouse.move(q['x']+110,q['y']+65,steps=5);page.mouse.up();page.locator('#modal [name=confirm]').check()
 nav('actions');assert 'My action center' in page.locator('h1').inner_text()
 actor('Employee');nav('calendar');click('v2-event');fill('title','QA personal reminder');fill('date','2026-11-28');submit();assert 'QA personal reminder' in page.locator('main').inner_text();actor('HR');assert 'QA personal reminder' not in page.locator('main').inner_text();print('PASS personal calendar event and actor separation')
 actor('Employee');nav('flow');click('new-request');fill('subject','QA three-stage approval');fill('body','Test sequential routing');sel('first','UC-002');sel('second','UC-003');click('v2-stage');sel('extraPerson','UC-004');submit();assert 'QA three-stage approval' in page.locator('main').inner_text();actor('Supervisor');nav('actions');assert 'QA three-stage approval' in page.locator('main').inner_text();nav('flow');row('QA three-stage approval').locator('button[data-action=request]').click();fill('reason','First stage passed');submit();actor('HR');nav('flow');row('QA three-stage approval').locator('button[data-action=request]').click();fill('reason','Second stage passed');submit();actor('Finance');nav('flow');row('QA three-stage approval').locator('button[data-action=request]').click();fill('reason','Third stage passed');submit();assert 'Approved' in row('QA three-stage approval').inner_text();print('PASS three-stage routing and assigned queue')
 actor('Employee');nav('attendance');row('UC-ATT-001').locator('button').click();click('new-request');fill('body','Correct time');fill('correctionTime','08:00');sel('first','UC-003');submit();actor('HR');nav('flow');row('Dispute UC-ATT-001').locator('button[data-action=request]').click();fill('reason','Verified correction');submit();nav('attendance');assert 'Corrected' in row('UC-ATT-001').inner_text();row('UC-ATT-001').locator('button').click();assert 'Submitted Time In: 08:02' in page.locator('#mb').inner_text();assert 'Effective attendance: 08:00' in page.locator('#mb').inner_text();click('close');nav('payroll');assert 'Awaiting payroll review' in page.locator('main').inner_text();click('v2-adjust');fill('reason','Reviewed for payroll');submit();assert 'Reviewed' in page.locator('main').inner_text();print('PASS attendance correction preserves original and creates payroll review')
 nav('docs');click('new-doc');sel('person','UC-001');sel('issuer','UC-002');fill('title','QA sign-before-delivery');fill('body','Sample document');submit();assert 'Awaiting company signature' in row('QA sign-before-delivery').inner_text();actor('Employee');nav('docs');assert 'QA sign-before-delivery' not in page.locator('main').inner_text();actor('Supervisor');nav('actions');page.locator('[data-action=doc]').filter(has_text='Open').click();draw();submit();actor('Employee');nav('docs');assert 'Issued' in row('QA sign-before-delivery').inner_text();row('QA sign-before-delivery').locator('button').click();draw();submit();assert 'Acknowledged' in row('QA sign-before-delivery').inner_text();print('PASS company signing gates employee delivery, then employee signs')
 actor('IT');nav('it');row('Photo upload fails').locator('button').click();click('v2-claim');assert 'In progress' in row('Photo upload fails').inner_text();print('PASS IT ticket claim and SLA display')
 actor('HR');nav('templates');click('new-template');page.locator('#modal input[name=source]').set_input_files({'name':'test.txt','mimeType':'text/plain','buffer':b'Hello {{employee.name}}'});page.wait_for_function("document.querySelector('#modal [name=body]').value.includes('Hello')");fill('name','QA text template');submit();row('QA text template').locator('button').click();with_download=page.expect_download();
 with with_download as dl: click('v2-tsx')
 assert dl.value.suggested_filename.endswith('.tsx');click('close');print('PASS TXT import and TSX export')
 click('v2-search');page.locator('#v2-search-input').fill('QA sign-before-delivery');assert 'QA sign-before-delivery' in page.locator('#v2-search-results').inner_text();click('close');print('PASS scoped global search')
 nav('home');page.screenshot(path='/tmp/uc-v2-desktop.png',full_page=True);page.set_viewport_size({'width':390,'height':844});page.locator('.menu').click();page.locator('.nav[data-value="calendar"]').click();assert page.locator('h1').is_visible();page.screenshot(path='/tmp/uc-v2-mobile.png',full_page=True);assert not errs,errs;print('PASS responsive calendar and no uncaught errors');b.close()
